with ranked as (select id, carrier, shipped_date, status from shipments qualify row_number() over (partition by status order by delivered_date, id) = 1) select date_trunc('quarter', shipped_date) as quarter_start, count(distinct carrier) as distinct_carriers, count(*) as event_count, size(collect_set(status)) as num_status, sort_array(collect_set(carrier)) as carrier_list, count(distinct id) as distinct_ids from ranked group by 1 order by num_status desc nulls first;
